#!/usr/bin/env python3
from pathlib import Path

root = Path(__file__).resolve().parents[2]
path = root / "src/frontend/parser_record.c"
text = path.read_text()

text = text.replace('#include <string.h>\n', '#include <limits.h>\n#include <string.h>\n', 1)

anchor = '''static bool parse_function_pointer_field_declarator(MinicParser *parser,\n                                                    MinicType return_type,\n                                                    MinicSourceSpan *name_span,\n                                                    MinicType *field_type) {\n'''
helper = '''static bool record_field_starts_parenthesized_pointer_array(const MinicParser *parser) {\n    MinicParser probe;\n    size_t depth;\n\n    if (parser == NULL || parser->current.kind != MINIC_TOKEN_LPAREN) {\n        return false;\n    }\n    probe = *parser;\n    if (!minic_parser_advance(&probe) || probe.current.kind != MINIC_TOKEN_STAR) {\n        return false;\n    }\n    depth = 0U;\n    for (;;) {\n        if (probe.current.kind == MINIC_TOKEN_LPAREN) {\n            depth += 1U;\n        } else if (probe.current.kind == MINIC_TOKEN_RPAREN) {\n            if (depth == 0U) {\n                return false;\n            }\n            depth -= 1U;\n            if (depth == 0U) {\n                return minic_parser_advance(&probe) &&\n                       probe.current.kind == MINIC_TOKEN_LBRACKET;\n            }\n        }\n        if (!minic_parser_advance(&probe)) {\n            return false;\n        }\n    }\n}\n\nstatic bool parse_pointer_to_array_field_declarator(MinicParser *parser,\n                                                     MinicType base_type,\n                                                     MinicSourceSpan *name_span,\n                                                     MinicType *field_type) {\n    unsigned int pointer_const_qualifiers;\n    unsigned int pointer_volatile_qualifiers;\n    MinicType type;\n    size_t pointer_depth;\n    size_t level;\n    bool is_array;\n\n    pointer_depth = 0U;\n    pointer_const_qualifiers = 0U;\n    pointer_volatile_qualifiers = 0U;\n    if (!minic_parser_expect(parser, MINIC_TOKEN_LPAREN,\n                             \"expected '(' before pointer-to-array field\")) {\n        return false;\n    }\n    while (parser->current.kind == MINIC_TOKEN_STAR) {\n        pointer_depth += 1U;\n        if (pointer_depth > sizeof(unsigned int) * CHAR_BIT ||\n            !minic_parser_advance(parser) ||\n            !minic_parser_parse_pointer_qualifier_sequence(parser, pointer_depth,\n                                                           &pointer_const_qualifiers,\n                                                           &pointer_volatile_qualifiers)) {\n            return false;\n        }\n    }\n    if (pointer_depth == 0U || parser->current.kind != MINIC_TOKEN_IDENTIFIER) {\n        minic_parser_error(parser, \"expected pointer-to-array field name\");\n        return false;\n    }\n    *name_span = parser->current.span;\n    if (!minic_parser_advance(parser) ||\n        !minic_parser_expect(parser, MINIC_TOKEN_RPAREN,\n                             \"expected ')' after pointer-to-array field\") ||\n        !minic_parser_parse_array_declarator_suffix(parser, base_type, true, &type, &is_array) ||\n        !is_array) {\n        return false;\n    }\n    for (level = 0U; level < pointer_depth; ++level) {\n        unsigned int bit = 1U << level;\n        if (!minic_type_pointer_to(type, &type)) {\n            minic_parser_error(parser, \"cannot build pointer-to-array field type\");\n            return false;\n        }\n        if ((pointer_const_qualifiers & bit) != 0U && !minic_type_add_const(type, &type)) {\n            return false;\n        }\n        if ((pointer_volatile_qualifiers & bit) != 0U && !minic_type_add_volatile(type, &type)) {\n            return false;\n        }\n    }\n    *field_type = type;\n    return true;\n}\n\nstatic bool parse_function_pointer_field_declarator(MinicParser *parser,\n                                                    MinicType return_type,\n                                                    MinicSourceSpan *name_span,\n                                                    MinicType *field_type) {\n'''
if text.count(anchor) != 1:
    raise SystemExit(f"function-pointer field anchor count={text.count(anchor)}")
text = text.replace(anchor, helper, 1)

old = '''    if (parser->current.kind == MINIC_TOKEN_LPAREN) {\n        if (!parse_function_pointer_field_declarator(parser, field_type, &name_span, &field_type)) {\n            return false;\n        }\n    } else {\n'''
new = '''    if (parser->current.kind == MINIC_TOKEN_LPAREN) {\n        if (record_field_starts_parenthesized_pointer_array(parser)) {\n            if (!parse_pointer_to_array_field_declarator(\n                    parser, field_type, &name_span, &field_type)) {\n                return false;\n            }\n        } else if (!parse_function_pointer_field_declarator(\n                       parser, field_type, &name_span, &field_type)) {\n            return false;\n        }\n    } else {\n'''
if text.count(old) != 1:
    raise SystemExit(f"record parenthesized field branch count={text.count(old)}")
path.write_text(text.replace(old, new, 1))
